content.text:
{
  "name": "通用套接字通信组件",
  "name_en": "Generic Socket Communication Layer",
  "manufacturer": "",
  "description": "这是一个非实体的软件通信组件，用于通过 TCP/IP 套接字与实验设备建立直接连接。它负责连接指定 IP 与端口，并处理命令写入、数据读取、查询收发，以及编码和读写终止符管理，常用于网络接口仪器的基础通信。",
  "description_en": "This is a non-physical software communication component for direct TCP/IP socket communication with laboratory devices. It opens a connection to a specified IP address and port and handles command writing, data reading, request-response queries, as well as encoding and read/write termination management for network-connected instruments.",
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化套接字连接到指定的 IP 地址和端口。",
      "description_en": "Initialize the socket connection to the specified IP address and port."
    },
    {
      "action_name": "auto-close",
      "description": "关闭套接字连接。",
      "description_en": "Close the socket connection."
    },
    {
      "action_name": "auto-write",
      "description": "向远程设备写入数据或命令。",
      "description_en": "Write data or commands to the remote device."
    },
    {
      "action_name": "auto-read",
      "description": "从远程设备读取数据。",
      "description_en": "Read data from the remote device."
    },
    {
      "action_name": "auto-query",
      "description": "向远程设备发送查询并读取返回结果。",
      "description_en": "Send a query to the remote device and read back the response."
    }
  ],
  "tag_hints": [
    "TCP/IP socket communication",
    "instrument networking",
    "command transport layer",
    "read/write termination handling",
    "device query interface",
    "generic lab communication"
  ]
}

